fn factorial(n):
  if n <= 1:
    ret 1
  ret n * factorial(n - 1)

fn is_prime(n):
  if n < 2:
    ret false
  let i = 2
  while i * i <= n:
    if n % i == 0:
      ret false
    i = i + 1
  ret true

