fn bubble_sort(arr):
  let n = len(arr)
  let result = []
  for item in arr:
    result.append(item)
  let i = 0
  while i < n:
    let j = 0
    while j < n - i - 1:
      if result[j] > result[j + 1]:
        let temp = result[j]
        result[j] = result[j + 1]
        result[j + 1] = temp
      j = j + 1
    i = i + 1
  ret result

fn binary_search(arr, target):
  let left = 0
  let right = len(arr) - 1
  while left <= right:
    let mid = (left + right) / 2
    if arr[mid] == target:
      ret mid
    if arr[mid] < target:
      left = mid + 1
    el:
      right = mid - 1
  ret -1

fn is_palindrome(s):
  let clean = s.lower()
  let reversed = ""
  let i = len(clean) - 1
  while i >= 0:
    reversed = reversed + clean[i]
    i = i - 1
  ret clean == reversed

