fn memoize(fn):
  let cache = {}
  def memoized(*args):
    let key = str(args)
    if key not in cache:
      cache[key] = fn(*args)
    ret cache[key]
  ret memoized

fn debounce(fn, delay):
  let last_call = 0
  def debounced(*args):
    let now = time()
    if now - last_call >= delay:
      last_call = now
      ret fn(*args)
  ret debounced

fn is_valid_email(email):
  if not email.contains("@"):
    ret false
  if not email.contains("."):
    ret false
  let parts = email.split("@")
  if len(parts) != 2:
    ret false
  if len(parts[0]) == 0 or len(parts[1]) == 0:
    ret false
  ret true

fn deep_clone(obj):
  if type(obj) == "list":
    let result = []
    for item in obj:
      result.append(deep_clone(item))
    ret result
  if type(obj) == "dict":
    let result = {}
    for key in obj:
      result[key] = deep_clone(obj[key])
    ret result
  ret obj

class Cache:
  fn init(self, ttl):
    self.ttl = ttl
    self.store = {}

  fn get(self, key):
    if key in self.store:
      let entry = self.store[key]
      if time() - entry["time"] < self.ttl:
        ret entry["value"]
      el:
        del self.store[key]
    ret none

  fn set(self, key, value):
    self.store[key] = {"value": value, "time": time()}

fn rate_limiter(max_requests, window):
  let requests = []
  def limited(fn):
    def wrapper(*args):
      let now = time()
      requests = [r for r in requests if now - r < window]
      if len(requests) >= max_requests:
        ret {"error": "Rate limit exceeded"}
      requests.append(now)
      ret fn(*args)
    ret wrapper
  ret limited

class EventEmitter:
  fn init(self):
    self.listeners = {}

  fn on(self, event, callback):
    if event not in self.listeners:
      self.listeners[event] = []
    self.listeners[event].append(callback)

  fn emit(self, event, *args):
    if event in self.listeners:
      for callback in self.listeners[event]:
        callback(*args)

