fn validate(data, rules):
  let errors = []
  for field, rule in rules:
    if rule == "required" and field not in data:
      errors.append(field + " is required")
    if rule == "email" and not is_valid_email(data[field]):
      errors.append(field + " must be a valid email")
    if rule == "number" and type(data[field]) != "number":
      errors.append(field + " must be a number")
  ret errors

