fn create_jwt(payload, secret):
  let header = {"alg": "HS256", "typ": "JWT"}
  let encoded_header = base64_encode(json_stringify(header))
  let encoded_payload = base64_encode(json_stringify(payload))
  let signature = sha256(encoded_header + "." + encoded_payload + secret)
  ret encoded_header + "." + encoded_payload + "." + signature

fn parse_query_string(qs):
  let params = {}
  if len(qs) == 0:
    ret params
  let pairs = qs.split("&")
  for pair in pairs:
    let parts = pair.split("=")
    if len(parts) == 2:
      params[parts[0]] = parts[1]
  ret params

